<?php
namespace App\Models;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Foundation\Auth\User as Authenticatable;use Illuminate\Notifications\Notifiable;use Laravel\Sanctum\HasApiTokens;class User extends Authenticatable{use HasApiTokens,HasFactory,Notifiable;protected $fillable=['student_no','name','email','password','role','section_id','instructor_name'];protected $hidden=['password','remember_token'];protected function casts():array{return ['email_verified_at'=>'datetime','password'=>'hashed'];}public function section(){return $this->belongsTo(Section::class);}}
